  const loStr = String(lo);
  const hiStr = String(hi);
  const len = loStr.length;

  if (len === 1) {
    const a = Number(loStr);
    const b = Number(hiStr);
    return a === b ? String(a) : `[${a}-${b}]`;
  }

  if (lo === hi) return loStr;

  const loFirst = Number(loStr[0]);
  const hiFirst = Number(hiStr[0]);
  const loRest = loStr.slice(1);
  const hiRest = hiStr.slice(1);

  if (loFirst === hiFirst) {
    return escapeDigitClass(loFirst) + fixedWidthRange(Number(loRest), Number(hiRest));
  }

  const restAllZeros = /^0+$/.test(loRest);
  const restAllNines = /^9+$/.test(hiRest);
  if (restAllZeros && restAllNines) {
