  }

  const parts = [];
  parts.push(escapeDigitClass(loFirst) + fixedWidthRange(Number(loRest), Number("9".repeat(len - 1))));
  if (hiFirst - loFirst > 1) {
    parts.push(`[${loFirst + 1}-${hiFirst - 1}]` + "\\d".repeat(len - 1));
  }
  parts.push(escapeDigitClass(hiFirst) + fixedWidthRange(Number("0".repeat(len - 1)), Number(hiRest)));

  return `(?:${parts.join("|")})`;
}

export function rangeToRegex(min, max, options = {}) {
  const { pad = false } = options;
  let lo = Math.trunc(min);
  let hi = Math.trunc(max);
  if (lo > hi) [lo, hi] = [hi, lo];

  if (!Number.isFinite(lo) || !Number.isFinite(hi)) {
    throw new TypeError("rangeToRegex expects finite numbers");
  }
  if (lo < 0) {
    throw new RangeError("rangeToRegex only supports non-negative integers");
  }

  const minLen = String(lo).length;
  const maxLen = String(hi).length;
  const parts = [];

  for (let len = minLen; len <= maxLen; len++) {
    const lower = Math.max(lo, len === 1 ? 0 : 10 ** (len - 1));
    const upper = Math.min(hi, 10 ** len - 1);
    if (lower > upper) continue;

    let body = fixedWidthRange(lower, upper);
    if (pad && len < maxLen) {
      body = `0{0,${maxLen - len}}${body}`;
